import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
  TextureLoader,
} from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  // --- Load texture from atlas ---
  const texLoader = ctx.textureLoader;
  const imgUrl = config.assets.imageUrl;
  const atlasTex = texLoader.load(imgUrl);

  // Source rect defines the region in the atlas. Here the whole image is used.
  // Set UV offset and repeat if needed (default full texture).
  // If the actual atlas is larger, adjust accordingly, but we assume 512x320.
  atlasTex.offset.set(0, 0);
  atlasTex.repeat.set(1, 1);

  // --- Build sprite plane (billboarded quad) ---
  const srcW = 512; // from source rect width
  const srcH = 320; // source rect height
  const aspect = srcW / srcH;
  const width = 1.0;
  const height = width / aspect; // ~0.625

  const geometry = new PlaneGeometry(width, height);
  const mapNode = texture(atlasTex);
  const material = new MeshBasicNodeMaterial({
    map: mapNode,
    transparent: true, // in case image has alpha
    depthWrite: false, // sprite-like
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    config.scenePlacement.position[0],
    config.scenePlacement.position[1],
    config.scenePlacement.position[2]
  );
  mesh.rotation.set(
    config.scenePlacement.rotation[0],
    config.scenePlacement.rotation[1],
    config.scenePlacement.rotation[2]
  );
  mesh.scale.set(
    config.scenePlacement.scale[0],
    config.scenePlacement.scale[1],
    config.scenePlacement.scale[2]
  );

  // --- Billboard handler ---
  mesh.userData.handlers = {
    update: (_delta, camera) => {
      mesh.lookAt(camera.position);
    },
    // No interaction handlers required (no interactions defined)
  };

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    // Dispose geometry and material (texture is cached by loader, skip disposal)
    geometry.dispose();
    material.dispose();
    // Remove from parent if any
    if (mesh.parent) {
      mesh.parent.remove(mesh);
    }
  };

  return mesh;
}
